contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public entry exercising forbidden-caller reverts for the three onlyOptimisticAsserter functions
    function run(address caller, bytes32 identifier, uint256 time, bytes calldata ancillaryData, bytes32 assertionId, bool truth) public payable {
        require(caller != address(0));
        // We will attempt to call the onlyOptimisticAsserter functions via low-level call with msg.sender = this contract.
        // Since optimisticAsserter is set in c at construction and equals the OptimisticAsserterInterface passed when c was deployed,
        // and our contract (InvMutTest) is not that address (checker deploys fresh c), these calls should revert when invoked directly.

        // Prepare calldata for requestPrice(identifier,time,ancillaryData)
        bytes memory reqPriceCalldata = abi.encodeWithSignature("requestPrice(bytes32,uint256,bytes)", identifier, time, ancillaryData);
        (bool okReq, ) = address(c).call(reqPriceCalldata);

        // Prepare calldata for assertionResolvedCallback(assertionId, truth)
        bytes memory resolvedCalldata = abi.encodeWithSignature("assertionResolvedCallback(bytes32,bool)", assertionId, truth);
        (bool okResolved, ) = address(c).call(resolvedCalldata);

        // Prepare calldata for assertionDisputedCallback(assertionId)
        bytes memory disputedCalldata = abi.encodeWithSignature("assertionDisputedCallback(bytes32)", assertionId);
        (bool okDisputed, ) = address(c).call(disputedCalldata);

        // The general rule: when called by someone who is not the optimisticAsserter, these functions revert (i.e., low-level call returns false)
        // We express that at least one of these low-level calls must have reverted if address(this) != optimisticAsserter.
        // Read optimisticAsserter getter from c
        address opt = address(c.optimisticAsserter());

        // If this contract is the optimisticAsserter, then none of them are required to revert; otherwise all three must revert.
        // Formulate: opt == address(this) OR (okReq == false && okResolved == false && okDisputed == false)
        assert(opt == address(this) || (okReq == false && okResolved == false && okDisputed == false));
    }

    // receive to accept ETH if needed by future extensions
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Single public entry exercising the onlyOptimisticAsserter guard for three functions.
    // Parameters: arbitrary inputs for the three calls.
    function run(bytes32 identifier, uint256 time, bytes calldata ancillaryData, bytes32 assertionId, bool truth) public payable {
        // Prepare to call the three external functions directly on c using the typed interface (top-level calls required).
        // These calls must be top-level statements and not nested.

        // Call requestPrice (state-changing on c, restricted by onlyOptimisticAsserter)
        bool okReq;
        try c.requestPrice(identifier, time, ancillaryData) {
            okReq = true;
        } catch {
            okReq = false;
        }

        // Call assertionResolvedCallback (state-changing on c, restricted)
        bool okResolved;
        try c.assertionResolvedCallback(assertionId, truth) {
            okResolved = true;
        } catch {
            okResolved = false;
        }

        // Call assertionDisputedCallback (state-changing on c, restricted)
        bool okDisputed;
        try c.assertionDisputedCallback(assertionId) {
            okDisputed = true;
        } catch {
            okDisputed = false;
        }

        // Read optimisticAsserter getter (view) to see which caller would be allowed.
        address opt = address(c.optimisticAsserter());

        // General rule: either this contract is the optimisticAsserter and then none of the three calls are required to revert,
        // or, if this contract is not the optimisticAsserter, all three restricted calls must have reverted.
        assert(opt == address(this) || (okReq == false && okResolved == false && okDisputed == false));
    }

    receive() external payable {}
}

