contract InvMutTest {
    C c;

    // store the optimisticAsserter address visible via public getter
    constructor(C _c) { c = _c; }

    // single public entry performing the property check
    // params: callerOverride indicates whether we try calling requestPrice as a different address
    // We cannot change msg.sender when calling c from this contract, but we can observe optimisticAsserter() and
    // check behavior when this contract (not optimisticAsserter) calls requestPrice: it must revert due to onlyOptimisticAsserter
    function run(bool expectRevertWhenNotAsserter, bytes32 identifier, uint256 time, bytes calldata ancillaryData) public payable {
        require(true);

        // Observe the optimisticAsserter address exposed by c
        address optAddr = address(c.optimisticAsserter());

        // If this contract is the optimisticAsserter (shouldn't be in normal deployment), then calling requestPrice should NOT revert.
        // Otherwise, calling requestPrice must revert because of the onlyOptimisticAsserter modifier.

        bool reverted;
        // Make the state-changing call as a top-level statement. It will be executed from this contract's address.
        try c.requestPrice(identifier, time, ancillaryData) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // The general rule: reverted == (optAddr != address(this))
        // However allow caller to indicate expectation flip via expectRevertWhenNotAsserter param so we can express a general relation
        // between the observed optimisticAsserter and whether the call reverted.
        // Concretely assert that if optimisticAsserter equals this contract, the call must not revert; if different, it must revert.
        assert(reverted == (optAddr != address(this)));
    }

    receive() external payable {}
}

