contract InvMutTest {
    C c;
    // We'll pass in an address that will act as the optimisticAsserter; the deployed C is fresh and expects that address
    constructor(C _c) { c = _c; }

    // Single public entry taking parameters for the price request
    function run(address optimisticAsserterCandidate, bytes32 identifier, uint256 time, bytes calldata ancillaryData) public payable {
        require(true);

        // Prepare calls: first, attempt to call requestPrice from this contract (not the optimistic asserter)
        bool revertedFromNonAsserter;
        try c.requestPrice(identifier, time, ancillaryData) {
            revertedFromNonAsserter = false;
        } catch {
            revertedFromNonAsserter = true;
        }

        // Now simulate call as if coming from optimisticAsserterCandidate by doing a low-level call (must be external call)
        // We cannot change msg.sender of our calls; but the contract C enforces onlyOptimisticAsserter by comparing msg.sender to optimisticAsserter (an immutable set at construction).
        // The checker deploys c with optimisticAsserter equal to some address; here we try a second call using address(c).call to forward a call from this contract
        // This cannot change msg.sender; however, to test the behavior we instead query the public getter optimisticAsserter and compare.

        // Read the optimisticAsserter stored in c to know which address is allowed
        address allowed = address(c.optimisticAsserter());

        // If this test contract is the allowed optimistic asserter, then calling requestPrice should succeed (not revert)
        bool revertedWhenAllowedCaller;
        if (allowed == address(this)) {
            try c.requestPrice(identifier, time, ancillaryData) {
                revertedWhenAllowedCaller = false;
            } catch {
                revertedWhenAllowedCaller = true;
            }
        } else {
            // If not allowed, calling as this contract must revert. We still call to observe behavior.
            try c.requestPrice(identifier, time, ancillaryData) {
                revertedWhenAllowedCaller = false;
            } catch {
                revertedWhenAllowedCaller = true;
            }
        }

        // The invariant to assert:
        // - If this contract is the registered optimisticAsserter, then requestPrice should NOT revert when called by this contract.
        // - If this contract is NOT the registered optimisticAsserter, then requestPrice SHOULD revert when called by this contract.
        // Also ensure that calling requestPrice (which is non-payable) did not change c's balance.

        uint256 balBefore = address(c).balance;
        // No state-changing calls except the requestPrice attempts above; read balance after
        uint256 balAfter = address(c).balance;

        assert(((allowed == address(this)) && (revertedWhenAllowedCaller == false) && (revertedFromNonAsserter == (allowed != address(this)))) || ((allowed != address(this)) && (revertedWhenAllowedCaller == true) && (revertedFromNonAsserter == true)) && (balBefore == balAfter));
    }

    receive() external payable {}
}

