    // We take inputs that would be forwarded to requestPrice; no Ether involved.
    function run(bytes32 identifier, uint256 time, bytes calldata ancillaryData) public payable {
        require(true);

        // Read the allowed optimistic asserter address from c (view call allowed inside function)
        address allowed = address(c.optimisticAsserter());

        // Record balance before attempts
        uint256 balBefore = address(c).balance;

        // Attempt calling requestPrice once (from this contract). Must be a top-level state-changing call wrapped in try/catch.
        bool revertedWhenCallerIsThis;
        try c.requestPrice(identifier, time, ancillaryData) {
            revertedWhenCallerIsThis = false;
        } catch {
            revertedWhenCallerIsThis = true;
        }

        // For comparison, attempt to call a view function to ensure we can still observe state (top-level): getAssertionPolicy is view
        // We pick an arbitrary assertionId (zero) to call the view; it's allowed inside function but must be a top-level statement when changing state — this is view so fine.
        EscalationManagerInterface.AssertionPolicy memory policy = c.getAssertionPolicy(bytes32(0));
        // Read balance again
        uint256 balAfter = address(c).balance;

        // General rule assertion:
        // If this contract equals the configured optimisticAsserter, requestPrice MUST NOT revert when called by this contract; otherwise it MUST revert.
        // Additionally, calling requestPrice (regardless of revert) must not change c's Ether balance.
        assert(((allowed == address(this)) == (!revertedWhenCallerIsThis)) && (balBefore == balAfter));
    }

    // Allow receiving ETH if needed by the harness (not used here)
    receive() external payable {}
}

