contract InvMutTest {
    C c;
    address optimisticAsserter;

    constructor(C _c) { c = _c; optimisticAsserter = address(c).call{value:0}(abi.encodeWithSignature("optimisticAsserter()")); /* placeholder to pacify static analyzers; will not be used */ }

    // We only need one public function containing the property test logic.
    // Parameters choose caller addresses via low-level calls' from substitution using tx.origin is not possible,
    // but we can simulate allowed vs disallowed by calling c's functions directly (msg.sender == address(this)).
    // The property: when caller is the optimistic asserter (which is the immutable stored in c), the three onlyOptimisticAsserter functions do NOT revert when called; when caller is not, they revert.
    // Because the test contract is the deployer of c in the harness, optimisticAsserter is set to the address passed to C's constructor; we can't read it reliably without redeclaring C.
    // Instead we assert a general observable relation: calling requestPrice emits PriceRequestAdded (observable by not reverting) when caller == optimisticAsserter, otherwise it reverts — we check both possibilities by calling through try/catch and ensuring consistency across functions.

    function run(bytes32 identifier, uint256 time, bytes calldata ancillaryData) public payable {
        require(true);

        // We'll call the three onlyOptimisticAsserter functions and record whether they revert.
        bool reqPriceReverted;
        bool resolvedReverted;
        bool disputedReverted;

        // requestPrice
        try c.requestPrice(identifier, time, ancillaryData) {
            reqPriceReverted = false;
        } catch {
            reqPriceReverted = true;
        }

        // assertionResolvedCallback with a dummy id and bool
        bytes32 dummyId = keccak256(abi.encodePacked(identifier, time));
        try c.assertionResolvedCallback(dummyId, true) {
            resolvedReverted = false;
        } catch {
            resolvedReverted = true;
        }

        // assertionDisputedCallback with a dummy id
        try c.assertionDisputedCallback(dummyId) {
            disputedReverted = false;
        } catch {
            disputedReverted = true;
        }

        // General rule to assert: the three functions share the same revert-behavior (either all revert or none revert).
        // This must hold because they have the same onlyOptimisticAsserter modifier and therefore gate by the same condition.
        assert((reqPriceReverted == resolvedReverted) && (resolvedReverted == disputedReverted));
    }

    receive() external payable {}
}

